WITH valid_orders AS (SELECT * FROM orders WHERE status IN ('RETURNED', 'COMPLETED', 'CANCELLED')), OrdersStats AS (SELECT CASE WHEN amount >= 1390 THEN 'high' WHEN amount >= 640 THEN 'mid' ELSE 'low' END amount_bucket, AVG(shipping_fee) avg_shipping_fee FROM valid_orders GROUP BY CASE WHEN amount >= 1390 THEN 'high' WHEN amount >= 640 THEN 'mid' ELSE 'low' END) SELECT * FROM OrdersStats ORDER BY amount_bucket
